import{_ as a,o,c as r,a2 as e}from"./chunks/framework.DpXDHk3d.js";const c=JSON.parse('{"title":"1.4 违反安全规定的法律责任","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/01-chapter-1-an-quan-sheng-chan-fa-l-fa-gui/1-4-wei-fan-an-quan-gui-ding-de-fa-l-ze-ren.md","filePath":"electrician/low-voltage-electrician/01-chapter-1-an-quan-sheng-chan-fa-l-fa-gui/1-4-wei-fan-an-quan-gui-ding-de-fa-l-ze-ren.md","lastUpdated":1793095197000}'),n={name:"electrician/low-voltage-electrician/01-chapter-1-an-quan-sheng-chan-fa-l-fa-gui/1-4-wei-fan-an-quan-gui-ding-de-fa-l-ze-ren.md"};function l(i,t,d,s,h,u){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="_1-4-违反安全规定的法律责任" tabindex="-1">1.4 违反安全规定的法律责任 <a class="header-anchor" href="#_1-4-违反安全规定的法律责任" aria-label="Permalink to &quot;1.4 违反安全规定的法律责任&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>&quot;后果&quot;才能让人重视安全。这一节讲清楚:如果违反安全规定,会面临<strong>行政责任、民事责任、刑事责任</strong>中的哪一种,什么情况下会&quot;坐牢&quot;。理解了后果,才懂得为什么规程一个字都不能省。</p><h2 id="一、三类法律责任" tabindex="-1">一、三类法律责任 <a class="header-anchor" href="#一、三类法律责任" aria-label="Permalink to &quot;一、三类法律责任&quot;">​</a></h2><table tabindex="0"><thead><tr><th>责任类型</th><th>由谁追究</th><th>后果形式</th><th>通俗理解</th></tr></thead><tbody><tr><td>行政责任</td><td>政府机关(应急管理、公安等)</td><td>警告、罚款、吊销证件、责令停产停业</td><td>&quot;被处罚&quot;</td></tr><tr><td>民事责任</td><td>法院(受害人起诉)</td><td>赔偿损失、赔礼道歉</td><td>&quot;赔钱&quot;</td></tr><tr><td>刑事责任</td><td>司法机关(公安、检察院、法院)</td><td>有期徒刑、拘役、罚金</td><td>&quot;坐牢&quot;</td></tr></tbody></table><h2 id="二、行政责任-最常见" tabindex="-1">二、行政责任(最常见) <a class="header-anchor" href="#二、行政责任-最常见" aria-label="Permalink to &quot;二、行政责任(最常见)&quot;">​</a></h2><p>违反安全规定,即使没出事故,也可能被行政处罚:</p><ul><li><strong>对个人</strong>:警告、罚款(如无证作业、转借证件等);</li><li><strong>对单位</strong>:责令改正、罚款、<strong>责令停产停业整顿</strong>、吊销有关许可证照;</li><li><strong>对持证人员</strong>:违反操作规程情节严重的,可能被<strong>吊销特种作业操作证</strong>,且规定年限内不得重新申请。</li></ul><blockquote><p>典型情形:电工无证上岗,单位被罚;电工将操作证借给别人用,本人证件被吊销并罚款。</p></blockquote><h2 id="三、民事责任" tabindex="-1">三、民事责任 <a class="header-anchor" href="#三、民事责任" aria-label="Permalink to &quot;三、民事责任&quot;">​</a></h2><p>因违章作业造成他人<strong>人身伤害或财产损失</strong>的,要承担民事赔偿责任:</p><ul><li>触电事故伤及路人或同事 → 医疗费、误工费、赔偿金;</li><li>电气火灾烧毁设备、财物 → 赔偿财产损失。</li></ul><blockquote><p>通俗理解:<strong>谁违章,谁担责赔钱</strong>。即便有保险,违章造成的损失也往往需要责任人承担。</p></blockquote><h2 id="四、刑事责任-高压线" tabindex="-1">四、刑事责任(高压线!) <a class="header-anchor" href="#四、刑事责任-高压线" aria-label="Permalink to &quot;四、刑事责任(高压线!)&quot;">​</a></h2><p>情节严重、构成犯罪的行为,会触犯《刑法》。与电工作业相关的常见罪名:</p><table tabindex="0"><thead><tr><th>罪名</th><th>对应行为</th><th>法律依据</th></tr></thead><tbody><tr><td><strong>重大责任事故罪</strong></td><td>在生产、作业中违反有关安全管理规定,造成重大伤亡事故或严重后果</td><td>《刑法》第 134 条</td></tr><tr><td><strong>强令、组织他人违章冒险作业罪</strong></td><td>强令他人违章冒险作业,发生重大事故</td><td>《刑法》第 134 条</td></tr><tr><td><strong>危险作业罪</strong></td><td>在生产、作业中违反安全管理规定,虽未发生事故但<strong>具有发生重大事故的现实危险</strong></td><td>《刑法》第 134 条之一(2021 年新增)</td></tr><tr><td><strong>重大劳动安全事故罪</strong></td><td>劳动安全设施不符合规定,导致重大事故</td><td>《刑法》第 135 条</td></tr></tbody></table><blockquote><p>⚠️ 重点理解:<strong>危险作业罪</strong>是 2021 年《刑法修正案(十一)》新增的罪名——<strong>不一定要出了事故才担责</strong>,只要&quot;具有发生重大事故的现实危险&quot;(比如违规储存危险物、无证作业高危作业等)就可能构罪。这体现了&quot;预防为主&quot;的思想。</p></blockquote><h2 id="五、典型案例-帮助理解" tabindex="-1">五、典型案例(帮助理解) <a class="header-anchor" href="#五、典型案例-帮助理解" aria-label="Permalink to &quot;五、典型案例(帮助理解)&quot;">​</a></h2><p><strong>案例一(行政责任)</strong>:某电工将本人特种作业操作证转借给无证的亲戚使用,被发现后,该电工被处以罚款,证件被吊销。</p><p><strong>案例二(刑事责任)</strong>:某工地电工在检修配电箱时,不执行停电、验电程序,带电拆线,造成触电身亡事故。经调查,该电工违反安全管理规定操作,构成重大责任事故罪,被追究刑事责任;现场负责人因安排无证人员带电作业,同样被追责。</p><blockquote><p>通过案例想记住的是:<strong>规程是用血换来的</strong>,带电作业、无证作业、强令违章作业都可能&quot;吃官司&quot;。</p></blockquote><h2 id="六、考点提示" tabindex="-1">六、考点提示 <a class="header-anchor" href="#六、考点提示" aria-label="Permalink to &quot;六、考点提示&quot;">​</a></h2><ul><li>✅ 《安全生产法》明确规定特种作业人员必须<strong>持证上岗</strong>,无证上岗要承担法律责任。</li><li>✅ 违反安全规定可能承担<strong>行政、民事、刑事</strong>三类责任。</li><li>✅ 2021 年《刑法修正案(十一)》新增<strong>危险作业罪</strong>:有现实危险即可构罪,不必等事故发生。</li><li>⚠️ 易混点:行政责任(罚款、吊销证件)与刑事责任(坐牢)别混淆,出了<strong>重大伤亡事故</strong>通常涉及刑事。</li></ul><h2 id="七、本节小结" tabindex="-1">七、本节小结 <a class="header-anchor" href="#七、本节小结" aria-label="Permalink to &quot;七、本节小结&quot;">​</a></h2><ul><li>违法后果:行政责任(罚)→ 民事责任(赔)→ 刑事责任(刑),逐级加重。</li><li>无证作业、转借证件、带电违章作业、强令冒险作业,都是重点违法情形。</li><li>&quot;预防为主&quot;体现在法律上:有重大风险未出事故也可能追责。</li></ul><h2 id="八、自测练习" tabindex="-1">八、自测练习 <a class="header-anchor" href="#八、自测练习" aria-label="Permalink to &quot;八、自测练习&quot;">​</a></h2><ol><li>(判断)违反安全生产规定,可能同时承担行政责任、民事责任和刑事责任。( )</li><li>(单选)将特种作业操作证转借给他人使用的,发证机关可以()。 A. 口头批评　B. 吊销证件　C. 不予追究　D. 只罚款不吊销</li><li>(判断)只有发生了重大伤亡事故,才可能承担刑事责任。( )</li><li>(单选)2021 年《刑法修正案(十一)》新增的罪名是()。 A. 重大责任事故罪　B. 重大劳动安全事故罪　C. 危险作业罪　D. 玩忽职守罪</li><li>(判断)生产经营单位安排无证人员从事特种作业,属于违法行为。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。三类责任并不互相排斥,情节严重时可能同时承担。</li><li><strong>B</strong>。转借证件属于严重违规,可能被吊销特种作业操作证并处罚款。</li><li><strong>×</strong>。危险作业罪只要有&quot;发生重大事故的现实危险&quot;即可构罪,不要求已发生事故。</li><li><strong>C</strong>。危险作业罪是 2021 年新增罪名,体现&quot;预防为主&quot;。</li><li><strong>√</strong>。《安全生产法》规定特种作业人员必须持证上岗,安排无证人员上岗属违法行为。</li></ol></details>',28)])])}const q=a(n,[["render",l]]);export{c as __pageData,q as default};
